def semver_sort(versions):
    def parse(v):
        core_build = v.split('+', 1)[0]
        if '-' in core_build:
            core, pre = core_build.split('-', 1)
        else:
            core, pre = core_build, None
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is not None:
            idents = pre.split('.')
            pre_key = []
            for ident in idents:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))
            has_pre = 0
        else:
            pre_key = []
            has_pre = 1
        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=parse)

